import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import facts from'./legacy-2018-pm-order-payment-facts.json';
export type PaymentRecord=[number,number,number,string];export type PaymentMapping={manual:number[];auto:number[];days:number};
const equal=(a:unknown,b:unknown)=>JSON.stringify(a)===JSON.stringify(b),SENTINEL=99999999;
/** Gregorian formula independent of producer and Date's serial conversion. */
export function paymentOrdinal(value:string){assert(/^\d{8}$/.test(value));const y=Number(value.slice(0,4)),m=Number(value.slice(4,6)),d=Number(value.slice(6));assert(y>=1601&&y<=9999&&m>=1&&m<=12);const months=[31,28+(y%4===0&&(y%100!==0||y%400===0)?1:0),31,30,31,30,31,31,30,31,30,31];assert(d>=1&&d<=months[m-1]);const p=y-1;return 365*p+Math.floor(p/4)-Math.floor(p/100)+Math.floor(p/400)+months.slice(0,m-1).reduce((a,b)=>a+b,0)+d;}
const NOW=paymentOrdinal('20180415');
export function paymentRecord(n:number,c:number,a:number,age:number):PaymentRecord{const dt=new Date(Date.UTC(2018,3,15-age));return[n,c,a,dt.toISOString().slice(0,10).replaceAll('-','')];}
function printed(n:number,result:string,invoice:number,receipt:number,difference:number){return{number:n,result,invoice,receipt,difference,text:String(n).padStart(8,'0')+' '.repeat(4)+result+' '.repeat(6)+invoice.toLocaleString('en-US').padStart(9)+' '.repeat(4)+receipt.toLocaleString('en-US').padStart(9)+' '.repeat(4)+difference.toLocaleString('en-US').padStart(10)};}
/** Independent business specification: union of keys, no streaming branch order. */
export function orderPaymentSpec(orders:PaymentRecord[],receipts:PaymentRecord[],m:PaymentMapping){const om=new Map(orders.map(r=>[r[0],r])),rm=new Map(receipts.map(r=>[r[0],r])),rows:ReturnType<typeof printed>[]=[],wait:PaymentRecord[]=[],display:string[]=[];for(const n of[...new Set([...om.keys(),...rm.keys()])].sort((a,b)=>a-b)){const o=om.get(n),r=rm.get(n);if(!o){rows.push(printed(n,'10',0,r![2],0));continue;}if(!r){if(m.auto.includes(o[1]))rows.push(printed(n,'00',o[2],0,0));else{wait.push(o);if(NOW-paymentOrdinal(o[3])>m.days)display.push(String(n).padStart(8,'0'));}}else rows.push(printed(n,o[2]===r[2]?'00':'20',o[2],r[2],r[2]-o[2]));}return{rows,wait,display};}
export class PaymentPortableBoundary extends Error{constructor(public kind:string,public state:Record<string,unknown>){super(kind);}}
const choiceText=(b:GeneratedBody,index:number)=>{const x=b.choices[index][0];assert(x.type==='code'||x.type==='paragraph');return x.text;};
const offsets=[0,4,4,10,14,18];
function predicate(s:string,o:PaymentRecord,r:PaymentRecord){if(s==='ORD-AMNT = RCP-AMNT')return o[2]===r[2];if(s==='ORD-AMNT = ZERO')return o[2]===0;if(s==='ORD-AMNT NOT = RCP-AMNT')return o[2]!==r[2];if(s==='ORD-CODE = RCP-CODE')return o[1]===r[1];const p=/^ORD-CODE = ([1-4]) OR ([1-4])$/.exec(s);assert(p);return o[1]===Number(p[1])||o[1]===Number(p[2]);}
/** Original execution order. Unknown size-error receiver stops portable inference,
 * never claims that an actual COBOL runtime must halt or raise an exception. */
export function orderPaymentStream(orders:PaymentRecord[],receipts:PaymentRecord[],m:PaymentMapping,body:GeneratedBody,key:number[]){let oi=0,ri=0,o:PaymentRecord=[0,0,0,'00000000'],r:PaymentRecord=[0,0,0,'00000000'];const rows:ReturnType<typeof printed>[]=[],wait:PaymentRecord[]=[],display:string[]=[];
 const readO=()=>{if(o[0]===SENTINEL)return;if(oi===orders.length)o[0]=SENTINEL;else o=[...orders[oi++]];},readR=()=>{if(r[0]===SENTINEL)return;if(ri===receipts.length)r[0]=SENTINEL;else r=[...receipts[ri++]];};
 const selected=key.map((n,i)=>choiceText(body,offsets[i]+n)),site=[/51.*52/,/53.*54/,/65.*66/,/71.*72/].findIndex(rx=>rx.test(selected[4]));assert(site>=0);
 const extra=(at:number)=>{if(site!==at)return;let gap:number;try{gap=NOW-paymentOrdinal(o[3]);}catch{throw new PaymentPortableBoundary('INVALID_DATE_ARGUMENT',{site:['between51and52','between53and54','between65and66','between71and72'][at],'ORD-DATE':o[3],'ORD-NO':o[0]});}if(gap<0||gap>999)throw new PaymentPortableBoundary('W_CNT_PIC9_3_SIZE_ERROR',{site:['between51and52','between53and54','between65and66','between71and72'][at],difference:gap,'ORD-DATE':o[3],'ORD-NO':o[0],firstUnrepresentableBeforeFComparison:true});const f=/^W-CNT (NOT =|<|=|>) (\d+)$/.exec(selected[5]);assert(f);const n=Number(f[2]),hit=f[1]==='<'?gap<n:f[1]==='='?gap===n:f[1]==='>'?gap>n:gap!==n;if(hit)display.push(String(o[0]).padStart(8,'0'));};
 readO();readR();for(let step=0;step<orders.length+receipts.length+3;step++){const oe=o[0]===SENTINEL,re=r[0]===SENTINEL;const done=selected[0]==='ORD-EOF'?oe:selected[0]==='RCP-EOF'?re:selected[0]==='ORD-EOF AND RCP-EOF'?oe&&re:oe||re;if(done)return{rows,wait,display};let n=o[0],result='  ',invoice=0,receipt=0,difference=0;if(o[0]<r[0]){if(predicate(selected[1],o,r)){result='00';extra(0);}else{wait.push([...o]);extra(1);}invoice=o[2];readO();}else if(o[0]===r[0]){if(predicate(selected[2],o,r))result='00';else{result='20';difference=r[2]-o[2];}invoice=o[2];receipt=r[2];extra(2);readO();readR();}else{result='10';receipt=r[2];n=r[0];extra(3);readR();}if(result!=='  '){if(selected[3]==='WRITE PRT-REC')rows.push(printed(n,result,invoice,receipt,difference));else if(selected[3]==='SET ORD-EOF RCP-EOF TO TRUE')o[0]=r[0]=SENTINEL;}}
 throw new PaymentPortableBoundary('BOUNDED_LOOP_DID_NOT_STOP',{key});}
export function observeOrderPayment(...args:Parameters<typeof orderPaymentStream>){try{return orderPaymentStream(...args);}catch(e){if(e instanceof PaymentPortableBoundary)return{boundary:e.kind,state:e.state};throw e;}}
export function orderPaymentCases(m:PaymentMapping):[PaymentRecord[],PaymentRecord[]][]{const a=m.auto,b=m.manual,d=m.days,R=paymentRecord;return[[[],[]],[[],[R(0,b[0],1,1)]],[[R(0,a[0],1,1)],[]],[[R(2,a[1],2,1)],[]],[[R(0,b[0],1,1)],[]],[[R(0,b[0],1,d)],[]],[[R(0,b[0],1,d+1)],[]],[[R(0,b[1],2,d+1)],[]],[[R(0,b[0],1,1)],[R(0,b[0],1,1)]],[[R(0,b[0],1,1)],[R(0,b[0],2,1)]],[[R(0,b[1],2,1)],[R(0,b[1],2,1)]],[[R(2,b[0],1,d+1)],[R(0,b[0],1,1)]],[[R(0,b[0],1,1),R(2,a[0],2,1)],[R(0,b[0],1,1),R(4,b[1],2,1)]]];}
export function orderPaymentMapping(values:number[]):PaymentMapping{const r=facts.mapping.find(r=>equal(r.values,values));assert(r,'independent fixed input domain');return r!.bound;}
/** Infer each required role from actual displayed choices and independent states. */
export function orderPaymentAnswerIndices(body:GeneratedBody,values:number[]){const m=orderPaymentMapping(values),answer:number[]=[];for(let part=0;part<6;part++){const accepted:number[]=[];for(let n=0;n<[4,6,6,4,4,4][part];n++){const s=choiceText(body,offsets[part]+n);let good=true;if(part===0){for(const oe of[false,true])for(const re of[false,true]){const got=s==='ORD-EOF'?oe:s==='RCP-EOF'?re:s==='ORD-EOF AND RCP-EOF'?oe&&re:s==='ORD-EOF OR RCP-EOF'?oe||re:undefined;good&&=got===(oe&&re);}}else if(part===1){for(const c of[1,2,3,4])for(const rc of[0,...m.manual])for(const a of[1,2])for(const r of[0,1,2])good&&=predicate(s,[0,c,a,'20180414'],[2,rc,r,'20180414'])===m.auto.includes(c);}else if(part===2){for(const c of m.manual)for(const a of[1,2])for(const r of[1,2])good&&=predicate(s,[0,c,a,'20180414'],[0,c,r,'20180414'])===(a===r);}else if(part===3)good=s==='WRITE PRT-REC';else if(part===4)good=/53.*54/.test(s);else{const f=/^W-CNT (NOT =|<|=|>) (\d+)$/.exec(s);assert(f);for(let gap=1;gap<=999;gap++){const k=Number(f[2]),got=f[1]==='<'?gap<k:f[1]==='='?gap===k:f[1]==='>'?gap>k:gap!==k;good&&=got===(gap>m.days);}}if(good)accepted.push(n);}assert.equal(accepted.length,1,'unique source role '+part);answer.push(accepted[0]);}return answer;}
export function legacy2018OrderPaymentOracle(body:GeneratedBody,values:number[]){const m=orderPaymentMapping(values),units=facts.sourceUnits as any[];assert.equal(body.prompt.length,34);assert.equal(body.choices.length,22);assert.equal(body.answerParts?.length,6);assert.deepEqual(body.answerParts![1].choiceIds,body.answerParts![2].choiceIds);assert.equal(body.answerParts!.reduce((s,p)=>s+p.choiceIds.length,0),28);
 for(const u of units){const n=Number(u.id.split('-')[1]);if(u.kind==='answer_group'||n>=29&&n<=31)continue;const index=n<=28?n:({32:30,36:31,37:32,38:33}as Record<number,number>)[n],b=body.prompt[index];if(u.kind==='figure'||u.kind==='table'){assert(b.type==='table'||b.type==='diagram');assert.equal(b.caption,u.caption);if(n===25){assert(b.type==='table');assert.deepEqual(b.columns,u.columns);assert.deepEqual(b.rows,u.rows);}else{assert(b.type==='diagram'&&b.scene.kind==='source_figure');const expected={...Object.fromEntries((n===37?['columns','rows']:['fields','headers','rows']).filter(k=>u[k]!==undefined).map(k=>[k,u[k]]))};assert.deepEqual(JSON.parse(b.alt),expected);assert.deepEqual(b.scene.values,[n===6?1:n===13?2:n===20?3:1]);assert.equal(b.scene.profile,n===37?'legacy-2018-order-payment-change-table':n===23?'legacy-2018-order-payment-print-format':'legacy-2018-order-payment-record-layout');}continue;}assert(b.type==='paragraph'||b.type==='heading');let expected=u.correctedText??u.text;if(n===10)expected=expected.replace('1，2，3，4',[...m.manual,...m.auto].join('，'));if(n===17)expected=expected.replace('1，2',m.manual.join('，'));if(n===36)expected=expected.replace('7日',m.days+'日');assert.equal(b.text,expected,'unit '+n);}
 const code=body.prompt[29];assert(code.type==='code');assert.equal(code.language,'cobol');assert.equal(code.text,'（行番号）\n'+facts.codeLines.map(r=>String(r.line).padStart(2,'0')+' '+r.text).join('\n'));assert.equal(body.contexts?.length,1);assert.equal(body.contexts![0].blocks[1].type,'paragraph');assert.equal((body.contexts![0].blocks[1]as{type:'paragraph';text:string}).text,facts.erratum.correctedText);const expected=orderPaymentAnswerIndices(body,values);body.partAnswers!.forEach((a,i)=>{assert(a.kind==='choice');assert.equal(a.partId,body.answerParts![i].id);assert.equal(a.choiceId,body.answerParts![i].choiceIds[expected[i]]);});assert(body.explanation.endsWith('W-CNTはPIC 9(3)で0〜999を表現できるが，日数差1000は収まらず，原題には表現不能時の処理は示されていない。'));assert(body.explanation.includes('W-CNT > '+m.days));assert(!body.explanation.includes('分けて扱う'));return expected;}
